const meta = $('Extract Email Metadata').item.json;
const bodyLower = (meta.bodyText || '').toLowerCase();
const subjectLower = (meta.subject || '').toLowerCase();

// Body is the primary signal; subject is only a fallback when the body gives
// no usable signal at all (see Classify Intent & Authorize Request for the
// same rule applied to registered customers).
function detect(text) {
  const wantsOpen = /\b(open an account|open account|new account|sign up|become a customer)\b/.test(text) && !/\bjoint\b/.test(text);
  const wantsPolicy = /\b(policy|policies|fee|fees|limit|limits|overdraft|credit card|interest rate|rule|rules|terms|hours|branch|support|help)\b/.test(text);
  return { wantsOpen, wantsPolicy };
}

let result = detect(bodyLower);
if (!result.wantsOpen && !result.wantsPolicy) {
  result = detect(subjectLower);
}

let fullName = null;
const fromMatch = String(meta.rawFrom || '').match(/^"?([^"<]+?)"?\s*<[^>]+>$/);
if (fromMatch && fromMatch[1].trim()) fullName = fromMatch[1].trim();
if (!fullName) {
  const nameMatch = meta.bodyText.match(/my name is\s+([A-Za-z][A-Za-z\s.'-]{1,60})/i);
  if (nameMatch) fullName = nameMatch[1].trim();
}
if (!fullName) fullName = meta.fromEmail.split('@')[0];

let accountType = 'checking';
if (/\bsavings?\b/.test(bodyLower + ' ' + subjectLower)) accountType = 'savings';

return [{ json: { wantsOpen: result.wantsOpen, wantsPolicy: result.wantsPolicy, fullName, accountType, fromEmail: meta.fromEmail, subject: meta.subject, bodyText: meta.bodyText } }];

const item = $input.first().json;
const text = ((item.subject||'') + ' ' + (item.bodyText||'')).toLowerCase();
let accountType = 'checking';
if (/\bsavings?\b/.test(text)) accountType = 'savings';

if (!item.jointInviteeEmail) {
  return [{ json: { ok: false, reason: 'We could not find an email address to invite. Please include it clearly, for example: "I want to open a joint account with bob@gmail.com".', fromEmail: item.fromEmail, subject: item.subject, full_name: item.full_name } }];
}

return [{ json: {
  ok: true,
  inviter_profile_id: item.profile_id,
  invitee_email: item.jointInviteeEmail,
  account_type: accountType,
  fromEmail: item.fromEmail,
  subject: item.subject,
  full_name: item.full_name
} }];

const meta = $('Extract Email Metadata').item.json;
const rows = $input.all().filter(r => r.json && r.json.id);
const invite = rows.length > 0 ? rows[0].json : null;

const bodyLower = (meta.bodyText || '').toLowerCase().trim();

// Guard against false positives: an ordinary transfer/balance/policy/account-
// opening email must NEVER be misread as an invitation response just because
// it happens to contain a common word like "yes". A real invitation reply is
// short and single-purpose, so we require either explicit phrasing, or a
// short reply with no other strong banking intent present.
const looksLikeOtherIntent = /\b(transfer|send money|remit|wire|balance|how much|policy|policies|\bfees?\b|\blimits?\b|overdraft|open an account|open account|new account|standing order|recurring|dispute|fraud|unauthorized|unauthorised)\b/.test(bodyLower);

const explicitAccept = /\bi accept\b|\baccept(?:s|ed|ing)? the invitation\b|\baccept this invitation\b/.test(bodyLower);
const explicitDecline = /\bi decline\b|\bdecline the invitation\b|\bdecline this invitation\b|\bi reject\b/.test(bodyLower);

const wordCount = bodyLower.split(/\s+/).filter(Boolean).length;
const isShortReply = wordCount > 0 && wordCount <= 8;
const shortAccept = isShortReply && /\b(accept|agree|yes|confirm|ok|okay)\b/.test(bodyLower);
const shortDecline = isShortReply && /\b(decline|reject|no|refuse)\b/.test(bodyLower);

const wantsAccept = explicitAccept || (shortAccept && !looksLikeOtherIntent);
const wantsDecline = explicitDecline || (shortDecline && !looksLikeOtherIntent);

const isResponse = !!invite && (wantsAccept || wantsDecline) && !(wantsAccept && wantsDecline);

return [{
  json: {
    isResponse,
    invitation_id: invite ? invite.id : null,
    accept: wantsAccept && !wantsDecline,
    fromEmail: meta.fromEmail,
    subject: meta.subject,
    bodyText: meta.bodyText,
    rawFrom: meta.rawFrom,
    messageId: meta.messageId,
    threadId: meta.threadId
  }
}];

