const res = $input.first().json;
const invitee = $('Detect Invitation Response Intent').item.json;

let inviteeMsg, inviterMsg;
const status = res.status || (res.success ? 'accepted' : 'error');

if (status === 'accepted') {
  inviteeMsg = `Your joint account has been created.\n\nAccount Number: ${res.account_number}\nCurrency: ${res.currency}\nStarting Balance: Rs 0.00`;
  inviterMsg = `Good news -- ${invitee.fromEmail} accepted your joint account invitation.\n\nAccount Number: ${res.account_number}\nCurrency: ${res.currency}`;
} else if (status === 'rejected') {
  inviteeMsg = `You have declined the joint account invitation. No account was created.`;
  inviterMsg = `${invitee.fromEmail} declined your joint account invitation. No account was created.`;
} else if (status === 'expired') {
  inviteeMsg = `This joint account invitation has expired (it was only valid for 5 minutes). Please ask the inviter to send a new one if you'd still like to proceed.`;
  inviterMsg = `Your joint account invitation to ${invitee.fromEmail} expired because they did not respond within 5 minutes. You can send a new invitation any time.`;
} else if (res.already_processed) {
  inviteeMsg = `This invitation was already ${res.status} -- no further action was taken.`;
  inviterMsg = null;
} else {
  inviteeMsg = `We could not process your response to this invitation. ${res.error || 'Please try again or contact support.'}`;
  inviterMsg = null;
}

return [{ json: {
  inviteeMsg,
  inviterMsg,
  inviteeEmail: invitee.fromEmail,
  inviterEmail: res.inviter_email || null
} }];

